#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

if (process.argv.includes('--version')) {
  const pkg = JSON.parse(fs.readFileSync(path.join(__dirname, 'package.json'), 'utf8'));
  console.log(pkg.version);
} else {
  console.log("hello");
}

